theme_fields.value:
.sided {
  margin: 1px 2px 3px 4px;
  padding-left: 10px;
  float: left;
  text-align: right;
  border-radius: 4px 0 0 4px;
  box-shadow: 2px 0 4px rgba($primary, .2);
  transform: translateX(-50%) rotate(15deg);
  background: url(arrow.png) left center no-repeat;
  background-position: 10px 50%;
  transition: left .2s, margin-right .2s;
  cursor: ne-resize;
  width: stretch;
  user-select: none;
  .inner { left: 0; right: auto; border-left: 1px solid $tertiary; }
}
:root { --sided-gap: light-dark(4px, 8px); }
.mode { padding-right: light-dark(1px, 2px); color-scheme: light dark; }
